import{_ as t,H as i,f as n,i as l}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"11 | Why：从Chat走向Act，我们还缺什么？","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是能做事儿（Act）的 Agent？","slug":"什么是能做事儿-act-的-agent","link":"#什么是能做事儿-act-的-agent","children":[]},{"level":2,"title":"有哪些方式可以提升 Agent 的 Act 能力？","slug":"有哪些方式可以提升-agent-的-act-能力","link":"#有哪些方式可以提升-agent-的-act-能力","children":[{"level":3,"title":"方式 1：模拟人类来操作数字世界。","slug":"方式-1-模拟人类来操作数字世界。","link":"#方式-1-模拟人类来操作数字世界。","children":[]},{"level":3,"title":"方式 2：调用与物理世界的接口 -function calling","slug":"方式-2-调用与物理世界的接口-function-calling","link":"#方式-2-调用与物理世界的接口-function-calling","children":[]}]},{"level":2,"title":"自助工单小助手是怎么做事儿的？","slug":"自助工单小助手是怎么做事儿的","link":"#自助工单小助手是怎么做事儿的","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"课后题","slug":"课后题","link":"#课后题","children":[]},{"level":2,"title":"参考：","slug":"参考","link":"#参考","children":[]}],"relativePath":"成为AGI产品经理/11｜Why：从Chat走向Act，我们还缺什么？.md","filePath":"成为AGI产品经理/11｜Why：从Chat走向Act，我们还缺什么？.md","lastUpdated":1795557342000}'),a={name:"成为AGI产品经理/11｜Why：从Chat走向Act，我们还缺什么？.md"};function p(s,e,o,g,A,r){return i(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="_11-why-从chat走向act-我们还缺什么" tabindex="-1">11 | Why：从Chat走向Act，我们还缺什么？ <a class="header-anchor" href="#_11-why-从chat走向act-我们还缺什么" aria-label="Permalink to &quot;11 | Why：从Chat走向Act，我们还缺什么？&quot;">​</a></h1><p>你好，我是产品二姐。</p><p>这节课我们会开启一个全新案例。前面的案例大多是 Chat 类的工作，让 Agent 帮我们梳理资料、回答问题。而这个案例，我们会让 Agent 做 Act 类的工作。当然，这里的 Act 并不是说要干体力活（那属于具身机器人的范畴），而是让人类可以通过 Agent 来操作软件系统，比如让Agent 帮我们在美团上订个外卖之类的。</p><p>我们的案例是让 Agent 下一个工单，做一个自助工单小助手的产品。在技术应用方面，除了之前用到的 RAG、提示词工程、Agent 设计、function calling 之外，还会使用微调技术来提升Agent 执行的准确率。</p><p>第一节，我会带你理解三个重点。一是什么是能做事（Act）的 Agent，也就是“自助工单小助手”这个产品做些什么事？二是有哪些方式可以实现 Agent 的 Act 能力？三是“自助工单小助手”</p><p>在做事儿的背后发生了什么。这部分内容能让你在未来的工作中准确识别哪些场景适合实现Act 类 Agent，即理解“锤子”的基础上找“钉子”。</p><p>第二节，我们会讨论微调模型对构建 Act 类的 Agent 来说有什么好处，以及作为产品经理，应该如何理解和应用这项技术？这部分内容既能帮你判断什么时候需要用到微调，又能帮你与技术、算法工程师更加融洽地合作。</p><p>第三节，我们会深入到“自助工单小助手”的实际场景，讨论如何准备微调数据，如何评估微调后的模型。这两部分内容也是 AI 产品经理在提示词工程之外的主要工作，在你在未来的工作中可以当做观摩案例。</p><p>目前，这类应用在市场上目前没有成熟的商业案例可以参考，甚至在我们目前的尝试中，准确率也难以达到商用水准，因此我会拿部分论文案例参考。尽管如此，它依然是未来的方向，正因如此，我希望你和我一起探索，在本门课的最后一个案例中走在市场前沿，为你未来的 AGI产品经理职业生涯做好知识预习！</p><h2 id="什么是能做事儿-act-的-agent" tabindex="-1">什么是能做事儿（Act）的 Agent？ <a class="header-anchor" href="#什么是能做事儿-act-的-agent" aria-label="Permalink to &quot;什么是能做事儿（Act）的 Agent？&quot;">​</a></h2><p>首先，我想引用阿里集团 CEO 吴永铭一句话来说明什么是 Act 类的 Agent。他说：</p><ul><li>深层次 AI 最大的想象力绝对不是在手机屏幕上做一两个超级 APP，而是接管数字世界，改变物理世界。</li></ul><p>这是他在最近 2024 年 9 月云栖大会上的发言。这句话怎么理解呢？我用三个例子来说明。</p><ul><li><p>例 1：2024 年 10 月，OpenAI 的开发者大会上，演讲中展示了 Agent 帮主人订咖啡的场景。</p></li><li><p>例 2：2024 年 9 月，蚂蚁金服旗下的支小宝发布大会上，展示了一个送奶茶到现场的例子。</p></li><li><p>例 3：在本门课第一章 03 节开头有个例子：当客户要求明天送货的时候，Agent 可以自动修改快递师傅的送货时间。</p></li></ul><p>这三个例子中，订咖啡、送奶茶、上门送货都是物理世界，而 AI 所操作的是数字世界。</p><p>过去几十年互联网的发展帮我们构建起了巨大的数字世界，它使人类与物理世界可以进行广泛链接。比如在某打车软件的 App 里，完成了出行工具、司机与乘客的链接；在某个购物 App里，完成了商品、卖家与买家的链接。</p><p>而 AI 带给我们的，就是把人类从数字世界中解放出来，让 Agent 代替人类完成这一链接。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/1.png" alt=""></a></p><p>在我们要讲的案例中，一个汽车企业客户希望做一个自助工单创建的小助手，他们希望 Agent在帮助车主解答问题的同时，还能根据故障情况安排师傅上门维修。也就是，让 Agent 接管“电动汽车车主 - 售后维修师傅 - 电动车及其设备”的数字世界。</p><p>我再用一段 Agent 与客户的对话来说明。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/2.png" alt=""></a></p><p>在这段简短对话中：</p><ul><li><p>首先客户反馈“充电桩坏了，需要报修”，接下来 Agent 追问故障信息。</p></li><li><p>然后客户反馈故障是“无法开机，拉闸拉不上去”，于是 Agent 回复“故障需要上门维修，并给客户三个时间选项。</p></li><li><p>最后客户回复“周三方便”，Agent 停留片刻后，就回复已经安排好，并把师傅的电话也一并发给客户。</p></li></ul><p>看到这里你可能会想：</p><ul><li><p>嗯～第一步 Agent 追问故障信息，这个应该是很自然的事情。</p></li><li><p>第二步中 Agent 判断上门维修可能是在 RAG 知识库里查到了类似的故障需要上门维修，但是它又是怎么知道周三、周四、周五这个时间的呢？不会是随便瞎说的吧。至于第三步，Agent 真的给安排师傅了吗？可不能随便给客户一个假消息，让客户白等一趟吧。</p></li></ul><p>其实，这些回复背后都是有充分的依据的。要达到这样的标准，就需要 Agent 的思考力和行动力，Agent 的思考力主要靠大语言模型本身来完成，实现方法上和之前 Chat 类的 Agent 是一致的，我们就不做详细讲解；而行动力需要 Agent 与外部世界进行准确链接来完成，我们把重点放在这一部分，看看有哪些方式可以提升 Agent 的行动力。</p><h2 id="有哪些方式可以提升-agent-的-act-能力" tabindex="-1">有哪些方式可以提升 Agent 的 Act 能力？ <a class="header-anchor" href="#有哪些方式可以提升-agent-的-act-能力" aria-label="Permalink to &quot;有哪些方式可以提升 Agent 的 Act 能力？&quot;">​</a></h2><p>目前业界有两种方式实现 Agent 的 Act 能力。</p><ol><li><p>模拟方式，即让 Agent 模拟人类操作。比如人类在网页上点击一个按钮，那么 Agent 也就执行一次点击操作。</p></li><li><p>函数调用方式，即 Agent 直接操作数字世界的接口或者函数来实现。比如通过 functioncalling 调用一次查询接口请求实现一次查询操作，这里 Agent 无需操作页面。</p></li></ol><p>我们一个个来讲。</p><h3 id="方式-1-模拟人类来操作数字世界。" tabindex="-1">方式 1：模拟人类来操作数字世界。 <a class="header-anchor" href="#方式-1-模拟人类来操作数字世界。" aria-label="Permalink to &quot;方式 1：模拟人类来操作数字世界。&quot;">​</a></h3><p>顾名思义，就是人类怎么操作数字世界，Agent 也怎么操作数字世界。</p><p>比如某旅游网站的 Agent 收到用户指令“给我订一张 23 号从北京到上海的晚上九点以后的机票”。那 Agent 的执行步骤就是：</p><ol><li><p>提取用户指令中的出发地， 目的地，出发日期。</p></li><li><p>找到网站上出发地， 目的地，出发时间这些字段，并将上述信息填入对应的输入框。</p></li><li><p>点击确认，提取网页中各个航班的信息，包括时间、价格、机场，即从网页 html 代码中提取出对应的页面元素。</p></li><li><p>提取出晚上九点以后的机票信息，返回给用户选择机票。</p></li><li><p>收到用户的选择。</p></li><li><p>点击对应机票的确认按钮。</p></li><li><p>填入乘机人信息。</p></li><li><p>点击提交订单。</p></li><li><p>请求用户输入账户密码。</p></li><li><p>点击确认，完成机票预订。</p></li></ol><p>这种方式的好处是不用改变数字世界本身。但这种方式在操作的时候需要做大量的信息提取工作。</p><p>在 Claude 的 Computer Use 中，通过多模态识别到屏幕上元素所在的像素点，然后通过点击该像素点实现。这种方式目前在一个开源数据集中的准确率是多少呢？14.9% [参考]，这是Claude 的测试结果，而这已经是非常领先了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/3.png" alt=""></a></p><p>另外一种方式是类似开源项目 Mind2Web 中，要从几百个网页元素中找到出发地、目的地、出发时间。这个过程中难免会发生提取错误。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/4.png" alt=""></a></p><p>虽然我们可以通过微调的方式提升 Agent 的网页元素识别准确率，但根据一些论文来看，微调后的准确率也没有超过 80%。比如开源项目mind2Web 中，作者收集了 137 个网站的页面信息，执行了 2350 个自然语言指令，记录了这些指令背后的页面操作步骤作为数据进行微调，网页元素识别的准确率仅仅为 55%。</p><p>另外，这种方式会把大量的无效信息（几百个网页元素的 html 代码）发送给模型，造成Token 浪费。我下载了部分数据后发现，仅仅一条自然语言指令对应的数据量大小大约是 40万 Token 数。如果在 OpenAI GPT3.5 模型的基础上微调，一条数据就要消耗 3.2 美元，成本令人咂舌。</p><ul><li>注：这里的成本计算方法是，mind2Web 的某个训练数据文件大小为 28MB，该文件中包含9 条训练数据。平均每条训练数据的文件大小约 3MB，约 3M 个字符，按照平均每个单词10 个字符算，约为 30 万个单词，折合为 40 万 Token 数，微调 openAI GPT3.5 的价格为$8/ 百万 Token，即 3.2 美元</li></ul><p>综合起来看，虽然这种方式不用改变现有系统，但如果直接让 Agent 模拟人类操作现有系统，准确率和成本都是难以克服的问题。所以，我们来看另外一种方式。</p><h3 id="方式-2-调用与物理世界的接口-function-calling" tabindex="-1">方式 2：调用与物理世界的接口 -function calling <a class="header-anchor" href="#方式-2-调用与物理世界的接口-function-calling" aria-label="Permalink to &quot;方式 2：调用与物理世界的接口 -function calling&quot;">​</a></h3><p>这种方式就是让 Agent 学会使用数字世界的接口来完成任务，同样是订机票的例子，这种方式操作的步骤是：</p><ol><li><p>识别用户意图，决定调用查询机票接口。</p></li><li><p>提取用户指令中的出发地， 目的地，出发时间。</p></li><li><p>将出发地， 目的地，出发时间填入查询接口的对应字段。</p></li><li><p>提取出晚上九点以后的机票信息，返回给用户选择机票。</p></li><li><p>收到用户的选择。</p></li><li><p>调用订单提交接口，将机票信息，乘机人信息填入接口的对应字段。</p></li><li><p>请求用户输入付款密码。</p></li><li><p>将付款信息与订单信息提交给支付接口，并返回请求结果。</p></li></ol><p>在这个过程中，模型完成了 3 次接口调用，这就要求现有系统能提供相对完善的接口，意味着有一定的接口改造工程。但是相比于模拟人类操作的方式，函数调用方式的准确率更高，比如业界标杆 OpenAI 的函数调用准确率大概是 85%（数据来源：2024 年 8 月数据伯克利大学Gorrilla 项目中的函数调用排行榜），高于上一种方式的 80%。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/5.png" alt=""></a></p><p>另外，Token 消耗也会有数量级的降低。在订机票的这个例子中约为 1.2 万 Token， 远低于上一种方法的 40 万 Token 数。</p><ul><li>采用函数调用法订机票的 Token 消耗计算方法：一个接口调用 Token 消耗 = （API 接口定义描述 + 自然语言指令） * （接口调用的错误次数 +1）</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/6.png" alt=""></a></p><p>最后，我把这两种方式对比来看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/7.png" alt=""></a></p><p>其实，在过去十年的数字化转型过程中，很多企业、软件系统已经完成了前后端分离的微服务架构建设，也就是开放了相对完备的接口服务，这也为 Agent 通过函数调用方式接管数字世界提供了较好的基础。所以综合来看，函数调用的方式似乎更具潜力。</p><p>在我们的自助工单小助手中，也会使用第二种方式来实现。我们接下来的任务，就是理解自助工单小助手的内部实现逻辑。</p><h2 id="自助工单小助手是怎么做事儿的" tabindex="-1">自助工单小助手是怎么做事儿的？ <a class="header-anchor" href="#自助工单小助手是怎么做事儿的" aria-label="Permalink to &quot;自助工单小助手是怎么做事儿的？&quot;">​</a></h2><p>我把这个过程放在下面这张图中，右侧绿色的是 Agent 需要在对话背后与接口做的交互，为了表述重点，我省略了某些细节步骤。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/11/8.png" alt=""></a></p><p>我们捋一下整个的任务流程。</p><ol><li><p>首先，客户反馈“充电桩坏了，需要报修”时， Agent 会做意图识别，将问题路由到TicketCreateAPI。在 TicketCreateAPI 中，Agent 会阅读 TicketCreateAPI 的接口定义，然后发现在这个接口中有几个必填字段。其中有些字段可以直接从用户信息获取，有一个字段是“故障信息”，它无法获得，于是据此生成了向客户咨询故障信息的问题。</p></li><li><p>接下来，当用户反馈故障表现时，再进行一次意图识别，Agent 要从充电桩维修知识库里搜索方案，然后发现这类问题需要师傅上门。</p></li><li><p>之后 Agent 会思考（Think）：需要查看师傅的可用时间；于是开始行动（Act）：调用SearchAvailableTime 接口，获取时间；接着观察到（Observation）：师傅周三、周四、周五有空；于是据此思考后生成回答，并向客户发出消息。细心的同学可能发现：咦？这不就是 Re-Act 的过程吗？ 没错，我们这里顺便就把上一个案例中的知识也回顾了一下。</p></li><li><p>后面的步骤，我想你对照着图就能理解这个过程了，这里就不再用文字详述。</p></li></ol><p>到这里，我们构建出了自助工单小助手这个产品的“期待模样”，Ta 应该具备以下能力。</p><ol><li><p>准确的意图识别、Query 重写和路由能力，这两项大家参考上一个案例即可。</p></li><li><p>让 Agent 正确地思考：比如在第二步当 Agent 发现需要师傅上门时，怎么能让他思考到需要查询师傅的可用时间呢？ 我把这个过程称为 workflow 学习，这部分和 Chat 类 Agent 的实现方法是一致的。</p></li><li><p>让 Agent 正确地行动：比如在调用 SearchAvailableTime 接口时，如何准确地将地址信息填入 SearchAvailableTime 接口的对应字段呢？这其实就是如何让 function calling 更准确，我把这个过程称为 function calling 学习，这部分是 Act 类 Agent 的必备能力，也是与Chat 类 Agent 最大的不同。</p></li></ol><p>别急，后面两个问题我们下两节课就来解决。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课，我们初步认识了什么是 Act 类的 Agent，从全球科技巨头的 Demo 中，我们可以确定地看到 Agent 从 Chat 走向 Act 的必然趋势。在这条路上，我们看到了人们同时在探索两条通往这个目标的路径，一个是模拟人类来操作数字世界，一个是调用与物理世界的接口。</p><p>在这两种路径中，采用函数调用的路径似乎更具潜力。但各位产品经理在未来的工作中，需要优先寻找那些已经具备完善的接口的“数字世界”，这里的启动更为容易，成本也会更低，Agent 实现数字世界的接管的道路也会更加畅通。</p><p>但即便如此，我们看到业界标杆的正确率（90%）还有上升空间，甚至这个正确率在真实场景中可能会更低，那么，有没有什么方法能提高准确率呢？ 我们下节课继续！</p><h2 id="课后题" tabindex="-1">课后题 <a class="header-anchor" href="#课后题" aria-label="Permalink to &quot;课后题&quot;">​</a></h2><p>下载蚂蚁金服的生活助手支小宝，让支小宝帮你做点“事”，测一测它执行得是否准确？</p><ul><li><p>对于执行较好的指令，想想它背后到底调用了什么样的接口？</p></li><li><p>对于执行错误的指令，想想如何才能让它做得更好？</p></li></ul><p>欢迎你在留言区和我交流。如果觉得有所收获，也可以把课程分享给更多的朋友一起学习。我们下节课见！</p><h2 id="参考" tabindex="-1">参考： <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考：&quot;">​</a></h2><p>Mind2Web：<a href="https://osu-nlp-group.github.io/Mind2Web/" target="_blank" rel="noreferrer">https://osu-nlp-group.github.io/Mind2Web/</a></p><blockquote><blockquote><p>戳此加入课程交流群</p></blockquote></blockquote>',74)])])}const u=t(a,[["render",p]]);export{c as __pageData,u as default};
